INSERT INTO training_plans(id,title,programme_id,training_group_id,season_id,week_start,created_by_id) SELECT ('39500000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,title,p.id,('39500000-0000-0000-0000-'||lpad(g::text,12,'0'))::uuid,'39500000-0000-0000-0000-000000000100',date_trunc('week',CURRENT_DATE)::date,'39500000-0000-0000-0000-000000000001' FROM programmes p CROSS JOIN(VALUES(300,'Semana pronta sintética',200,'Leisure'),(301,'Semana origem sintética',201,'Competition'),(302,'Semana outra origem',202,'Competition'),(303,'Semana origem reservada',203,'Kayak_Polo'))f(n,title,g,code2) WHERE p.code=code2;
